        return SourceBitmapRef(
            atlasFileName = "rastersymbols-day.png",
            x = p[0], y = p[1], width = p[2], height = p[3],
            pivotX = p[4], pivotY = p[5], originX = p[6], originY = p[7]
        )
    }
    private fun String.dec(): String = buildString {
        var escaping = false
        for (ch in this@dec) {
            if (escaping) {
                append(when (ch) { 't' -> '\t'; 'n' -> '\n'; 'r' -> '\r'; '\\' -> '\\'; else -> ch })
                escaping = false
            } else if (ch == '\\') escaping = true else append(ch)
        }
        if (escaping) append('\\')
    }

